# Ronde 12: functie eerst, vorm daarna (idempotent, verwijdert niets)
import sqlite3;c=sqlite3.connect('canon.db')
TAG='[Uitwerking (r12)'
def ex(t,code): return c.execute(f"select 1 from {t} where code=?",(code,)).fetchone()
def add(cat,code,o,f,r,refs,**kw):
  if ex('canon',code): return 0
  k=['categorie','onderwerp','feit','status','reden','hangt_samen_met','ronde','code','verwijst_naar']+list(kw)
  v=[cat,o,f,'voorlopig',r,refs,12,code,refs]+list(kw.values())
  c.execute(f"insert into canon({','.join(k)}) values({','.join('?'*len(k))})",v);return 1
n=0
# 1. Functies: probleem, mechanisme, belang (wereld/huis/individu), wie, alternatieven, prijs, inteelt
