# markeer meta-vorm
r=c.execute("select feit from canon where code='LICH-macht-en-lichaam'").fetchone()
if r and '[Markering r12' not in r[0]:
  c.execute("update canon set feit=feit||' [Markering r12: dit is een overkoepelend principe, geen eigen vorm; concrete vormen zijn LICH-moederblindheid, LICH-tribunaalteken, LICH-goudmasker.]' where code='LICH-macht-en-lichaam'");n+=1
# PLEK bijwerken met nieuwe vormen
pl={}
for code,_,_,_,_,_,_,_,_,_,_,_,_,links in NL:
  for x in links.split(';'):
    if x.startswith('PLEK-LICH-'): pl.setdefault(x,[]).append(code)
for p,items in pl.items():
  r=c.execute("select feit from canon where code=?",(p,)).fetchone()
  if r and '[Nieuwe vormen (r12)' not in r[0]:
    c.execute("update canon set feit=feit||?,verwijst_naar=verwijst_naar||? where code=?",(f" [Nieuwe vormen (r12): {', '.join(items)}.]",';'+';'.join(items),p));n+=1
# matrix
LICH=[(a,b) for a,b in c.execute("select code,functie from canon where code like 'LICH-%' and functie is not null")]
M={k:[a for a,b in LICH if k in b.split(';')] for k in FU}
mat='; '.join(f"{k}: {len(v)} ({', '.join(x[5:] for x in v)})" for k,v in M.items())
n+=add('Lichaam en vervorming','FUNC-matrix','Matrix functie × vorm',f"Na ronde 12: {mat}. Gaten vóór r12: SELECT en DIPLO hadden 0 vormen; LUST, OVERG, POL en VOORT hadden er 1-3. Vormen zonder eigen functie: LICH-macht-en-lichaam (overkoepelend, gemarkeerd). LICH-vonkkoorts heeft LUST alleen indirect.",'Ronde 12','FUNC-overzicht')
